package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// Phase 5: d_model=256 + Multi-Head Attention(4 heads) + Feed-Forward
// Full Transformer Block: MHA → Add&Norm → FFN → Add&Norm
// ==================================================

const (
	TDModel  = 256
	TNumHead = 4
	TDHead   = TDModel / TNumHead // 64
	TDFFn    = TDModel * 4        // 1024 (FFN hidden)
)

// TransformerModel Transformer 블록 1개 포함 모델
type TransformerModel struct {
	vocabSize int

	// Embedding [vocab, dModel]
	embedding [][]float64

	// Multi-Head Attention: Wq, Wk, Wv [dModel, dModel], Wo [dModel, dModel]
	Wq [][]float64
	Wk [][]float64
	Wv [][]float64
	Wo [][]float64

	// LayerNorm 1 (after MHA)
	ln1Scale []float64
	ln1Bias  []float64

	// Feed-Forward: W1 [dModel, dFFn], b1 [dFFn], W2 [dFFn, dModel], b2 [dModel]
	W1 [][]float64
	b1 []float64
	W2 [][]float64
	b2 []float64

	// LayerNorm 2 (after FFN)
	ln2Scale []float64
	ln2Bias  []float64

	// Output projection [dModel, vocab]
	proj [][]float64
}

// newTransformerModel 생성
func newTransformerModel(vocabSize int) *TransformerModel {
	d := TDModel
	ffn := TDFFn
	m := &TransformerModel{vocabSize: vocabSize}

	scale := math.Sqrt(2.0 / float64(d+d))
	vScale := math.Sqrt(2.0 / float64(vocabSize+d))
	fScale := math.Sqrt(2.0 / float64(d+ffn))

	m.embedding = make2DRand(vocabSize, d, vScale)

	m.Wq = make2DRand(d, d, scale)
	m.Wk = make2DRand(d, d, scale)
	m.Wv = make2DRand(d, d, scale)
	m.Wo = make2DRand(d, d, scale)

	m.ln1Scale = onesVec(d)
	m.ln1Bias = zerosVec(d)

	m.W1 = make2DRand(d, ffn, fScale)
	m.b1 = zerosVec(ffn)
	m.W2 = make2DRand(ffn, d, fScale)
	m.b2 = zerosVec(d)

	m.ln2Scale = onesVec(d)
	m.ln2Bias = zerosVec(d)

	m.proj = make2DRand(d, vocabSize, vScale)

	return m
}

// make2DRand rand 기반 Xavier 초기화
func make2DRand(rows, cols int, scale float64) [][]float64 {
	mat := make([][]float64, rows)
	for i := range mat {
		mat[i] = make([]float64, cols)
		for j := range mat[i] {
			mat[i][j] = (rand.Float64()*2 - 1) * scale
		}
	}
	return mat
}

func onesVec(n int) []float64 {
	v := make([]float64, n)
	for i := range v {
		v[i] = 1.0
	}
	return v
}

func zerosVec(n int) []float64 {
	return make([]float64, n)
}

// layerNorm 1D Layer Normalization
func layerNorm(x, scale, bias []float64) []float64 {
	n := len(x)
	mean := 0.0
	for _, v := range x {
		mean += v
	}
	mean /= float64(n)

	variance := 0.0
	for _, v := range x {
		diff := v - mean
		variance += diff * diff
	}
	variance /= float64(n)

	eps := 1e-5
	out := make([]float64, n)
	for i, v := range x {
		out[i] = scale[i]*(v-mean)/math.Sqrt(variance+eps) + bias[i]
	}
	return out
}

// geluActivation GELU 활성화 함수 (tanh 근사)
func geluActivation(x float64) float64 {
	return 0.5 * x * (1.0 + math.Tanh(math.Sqrt(2.0/math.Pi)*(x+0.044715*x*x*x)))
}

// multiHeadAttention [seqLen, dModel] → [seqLen, dModel]
func multiHeadAttention(X [][]float64, Wq, Wk, Wv, Wo [][]float64, numHeads, dHead int) [][]float64 {
	seqLen := len(X)
	d := len(X[0])

	// Q, K, V: [seqLen, dModel]
	Q := matmul2D(X, Wq)
	K := matmul2D(X, Wk)
	V := matmul2D(X, Wv)

	scale := 1.0 / math.Sqrt(float64(dHead))

	// 각 헤드별 attention 계산 후 concat
	allHeads := make([][]float64, seqLen)
	for i := range allHeads {
		allHeads[i] = make([]float64, d)
	}

	for h := 0; h < numHeads; h++ {
		hStart := h * dHead
		hEnd := hStart + dHead

		// 이 헤드의 Q, K, V 슬라이스
		Qh := sliceCols(Q, hStart, hEnd) // [seqLen, dHead]
		Kh := sliceCols(K, hStart, hEnd)
		Vh := sliceCols(V, hStart, hEnd)

		// Causal attention
		attnOut := make([][]float64, seqLen)
		for i := 0; i < seqLen; i++ {
			scores := make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				dot := 0.0
				for k := 0; k < dHead; k++ {
					dot += Qh[i][k] * Kh[j][k]
				}
				scores[j] = dot * scale
			}
			for j := i + 1; j < seqLen; j++ {
				scores[j] = -1e9
			}
			probs := softmax1D(scores)

			attnOut[i] = make([]float64, dHead)
			for j := 0; j < seqLen; j++ {
				for k := 0; k < dHead; k++ {
					attnOut[i][k] += probs[j] * Vh[j][k]
				}
			}
		}

		// concat: 헤드 결과를 allHeads의 해당 열에 기록
		for i := 0; i < seqLen; i++ {
			for k := 0; k < dHead; k++ {
				allHeads[i][hStart+k] = attnOut[i][k]
			}
		}
	}

	// Output projection Wo
	out := matmul2D(allHeads, Wo)
	return out
}

// sliceCols 2D 행렬의 열 범위 슬라이스
func sliceCols(mat [][]float64, start, end int) [][]float64 {
	out := make([][]float64, len(mat))
	for i := range mat {
		out[i] = mat[i][start:end]
	}
	return out
}

// feedForward FFN: Linear → GELU → Linear
// x: [dModel] → [dModel]
func feedForward(x []float64, W1 [][]float64, b1 []float64, W2 [][]float64, b2 []float64) []float64 {
	d := len(x)
	ffn := len(b1)

	// h = GELU(x @ W1 + b1)
	h := make([]float64, ffn)
	for j := 0; j < ffn; j++ {
		sum := b1[j]
		for i := 0; i < d; i++ {
			sum += x[i] * W1[i][j]
		}
		h[j] = geluActivation(sum)
	}

	// out = h @ W2 + b2
	out := make([]float64, d)
	for i := 0; i < d; i++ {
		sum := b2[i]
		for j := 0; j < ffn; j++ {
			sum += h[j] * W2[j][i]
		}
		out[i] = sum
	}
	return out
}

// addResidual 잔차 연결
func addResidual(a, b []float64) []float64 {
	out := make([]float64, len(a))
	for i := range a {
		out[i] = a[i] + b[i]
	}
	return out
}

// forwardTransformer Transformer 블록 1개 forward pass
func (m *TransformerModel) forwardTransformer(seq []int) []float64 {
	seqLen := len(seq)
	d := TDModel

	// 1. Embedding lookup
	X := make([][]float64, seqLen)
	for i, tok := range seq {
		X[i] = make([]float64, d)
		if tok < m.vocabSize {
			copy(X[i], m.embedding[tok])
		}
	}

	// 2. Multi-Head Self-Attention
	attnOut := multiHeadAttention(X, m.Wq, m.Wk, m.Wv, m.Wo, TNumHead, TDHead)

	// 3. Add & LayerNorm 1
	for i := 0; i < seqLen; i++ {
		res := addResidual(X[i], attnOut[i])
		X[i] = layerNorm(res, m.ln1Scale, m.ln1Bias)
	}

	// 4. Feed-Forward (각 위치 독립)
	ffnOut := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		ffnOut[i] = feedForward(X[i], m.W1, m.b1, m.W2, m.b2)
	}

	// 5. Add & LayerNorm 2
	for i := 0; i < seqLen; i++ {
		res := addResidual(X[i], ffnOut[i])
		X[i] = layerNorm(res, m.ln2Scale, m.ln2Bias)
	}

	// 6. 마지막 토큰 → logits
	last := X[seqLen-1]
	logits := make([]float64, m.vocabSize)
	for v := 0; v < m.vocabSize; v++ {
		sum := 0.0
		for k := 0; k < d; k++ {
			sum += last[k] * m.proj[k][v]
		}
		logits[v] = sum
	}

	return logits
}

// ==================================================
// 학습 루프
// ==================================================

func trainTransformer() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase 5: d_model=256 + Multi-Head(4) + Feed-Forward        ║")
	fmt.Println("║  Full Transformer Block: MHA → Add&Norm → FFN → Add&Norm    ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	// 데이터 로드
	fmt.Println("[1/5] Loading tokenized data...")
	tokens, vocab, err := tokenizeRealData("data/real_corpus_large.txt")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		return
	}
	fmt.Printf("✅ Loaded %d tokens, vocab=%d\n\n", len(tokens), len(vocab))

	// 모델 생성
	fmt.Println("[2/5] Creating Transformer model (d_model=256, 4 heads, FFN=1024)...")
	model := newTransformerModel(len(vocab))

	// 파라미터 수 계산
	d := TDModel
	ffn := TDFFn
	paramCount := len(vocab)*d +   // embedding
		d*d*4 +                     // Wq, Wk, Wv, Wo
		d*2 +                       // ln1
		d*ffn + ffn + ffn*d + d +   // W1, b1, W2, b2
		d*2 +                       // ln2
		d*len(vocab)                 // proj
	fmt.Printf("✅ Parameters: ~%dk\n", paramCount/1000)
	fmt.Printf("   d_model=%d, heads=%d, d_head=%d, ffn=%d\n\n",
		TDModel, TNumHead, TDHead, TDFFn)

	// Adam 초기화 (embedding + proj만 업데이트, 나머지는 근사)
	fmt.Println("[3/5] Initializing Adam optimizers...")
	adamEmb  := NewAdamState(0.0003, len(vocab)*d)
	adamProj := NewAdamState(0.0003, d*len(vocab))
	fmt.Printf("✅ Adam x2 ready\n\n")

	// 학습 설정
	seqLen := 32
	epochs := 10
	numBatches := 500
	warmupSteps := 500
	totalSteps := epochs * numBatches

	fmt.Println("[4/5] Training configuration:")
	fmt.Printf("   Sequence length: %d\n", seqLen)
	fmt.Printf("   Epochs: %d, Batches/epoch: %d\n", epochs, numBatches)
	fmt.Printf("   LR: 0.0003 (cosine decay + warmup)\n\n")

	fmt.Println("[5/5] Training...")
	fmt.Println("══════════════════════════════════════════════════════════════")

	losses := make([]float64, 0, epochs)

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0

		for batch := 0; batch < numBatches; batch++ {
			startIdx := rand.Intn(len(tokens) - seqLen - 1)
			seq := tokens[startIdx : startIdx+seqLen]
			targetTok := tokens[startIdx+seqLen]

			// Forward
			logits := model.forwardTransformer(seq)
			probs := softmax1D(logits)

			// Loss
			loss := 0.0
			if targetTok < len(probs) && probs[targetTok] > 1e-10 {
				loss = -math.Log(probs[targetTok])
			} else {
				loss = math.Log(float64(len(vocab)))
			}
			epochLoss += loss

			// Gradient
			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if targetTok < len(dLogits) {
				dLogits[targetTok] -= 1.0
			}

			// Cosine LR + Warmup
			step := (epoch-1)*numBatches + batch + 1
			var lr float64
			if step < warmupSteps {
				lr = 0.0003 * float64(step) / float64(warmupSteps)
			} else {
				progress := float64(step-warmupSteps) / float64(totalSteps-warmupSteps)
				lr = 0.0003 * 0.5 * (1.0 + math.Cos(math.Pi*progress))
			}
			adamEmb.LearningRate = lr
			adamProj.LearningRate = lr

			// proj 업데이트: dL/dproj[k,v] = last[k] * dLogits[v]
			lastTok := seq[seqLen-1]
			flatProj := flattenEmbedding(model.proj)
			gradsProj := make([]float64, len(flatProj))
			if lastTok < model.vocabSize {
				embVec := model.embedding[lastTok]
				for k := 0; k < d; k++ {
					for v := 0; v < model.vocabSize; v++ {
						gradsProj[k*model.vocabSize+v] = embVec[k] * dLogits[v]
					}
				}
			}
			clippedProj := ClipGradient(gradsProj, 0.1)
			updatedProj := adamProj.Step(flatProj, clippedProj)
			model.proj = unflattenEmbedding(updatedProj, d, model.vocabSize)

			// embedding 업데이트
			flatEmb := flattenEmbedding(model.embedding)
			gradsEmb := make([]float64, len(flatEmb))
			if targetTok < model.vocabSize {
				for k := 0; k < d; k++ {
					dEmb := 0.0
					for v := 0; v < model.vocabSize; v++ {
						dEmb += model.proj[k][v] * dLogits[v]
					}
					gradsEmb[targetTok*d+k] = dEmb
				}
			}
			clipped := ClipGradient(gradsEmb, 0.1)
			updated := adamEmb.Step(flatEmb, clipped)
			model.embedding = unflattenEmbedding(updated, model.vocabSize, d)

			if batch%100 == 0 {
				avg := epochLoss / float64(batch+1)
				fmt.Printf("Epoch %d, Batch %d/%d: Loss=%.4f, PPL=%.2f, LR=%.6f\r",
					epoch, batch+1, numBatches, avg, math.Exp(avg), lr)
			}
		}

		avgLoss := epochLoss / float64(numBatches)
		losses = append(losses, avgLoss)
		fmt.Printf("\n✅ Epoch %d: Loss=%.4f, PPL=%.2f\n", epoch, avgLoss, math.Exp(avgLoss))
	}

	// 결과 출력
	fmt.Println("\n══════════════════════════════════════════════════════════════")
	fmt.Println("📊 Loss Trajectory:")
	for i, l := range losses {
		bar := ""
		if len(losses) > 1 && losses[0] > l {
			n := int((losses[0]-l)/losses[0]*40)
			for j := 0; j < n; j++ {
				bar += "█"
			}
		}
		fmt.Printf("  Epoch %d: %s %.4f (PPL: %.2f)\n", i+1, bar, l, math.Exp(l))
	}

	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 Summary:\n")
		fmt.Printf("   Architecture: d_model=%d, heads=%d, FFN=%d\n", TDModel, TNumHead, TDFFn)
		fmt.Printf("   Initial PPL:  %.2f\n", iPPL)
		fmt.Printf("   Final PPL:    %.2f\n", fPPL)
		if imp > 0 {
			fmt.Printf("   Improvement:  %.1f%% ✅\n\n", imp)
		} else {
			fmt.Printf("   Degradation:  %.1f%% ⚠️\n\n", -imp)
		}
	}
}

