			} else {
				loss = math.Log(float64(len(vocab)))
			}
			epochLoss += loss

			// Gradient
			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if targetTok < len(dLogits) {
				dLogits[targetTok] -= 1.0
			}

			// Cosine LR + Warmup
			step := (epoch-1)*numBatches + batch + 1
			var lr float64
			if step < warmupSteps {
				lr = 0.0003 * float64(step) / float64(warmupSteps)
			} else {
				progress := float64(step-warmupSteps) / float64(totalSteps-warmupSteps)
				lr = 0.0003 * 0.5 * (1.0 + math.Cos(math.Pi*progress))
			}
			adamEmb.LearningRate = lr
			adamProj.LearningRate = lr

			// proj 업데이트: dL/dproj[k,v] = last[k] * dLogits[v]
			lastTok := seq[seqLen-1]
