			}
		}

		avgLoss := epochLoss / float64(numBatches)
		losses = append(losses, avgLoss)
		fmt.Printf("\n✅ Epoch %d: Loss=%.4f, PPL=%.2f\n", epoch, avgLoss, math.Exp(avgLoss))
	}

	// 결과 출력
	fmt.Println("\n══════════════════════════════════════════════════════════════")
	fmt.Println("📊 Loss Trajectory:")
