package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// Phase 6: 2 Transformer Blocks + 20 Epochs
// d_model=256, 4-head MHA, FFN=1024, 2 layers
// ==================================================

// TransformerBlock 단일 블록 (MHA + FFN + LayerNorm x2)
type TransformerBlock struct {
	Wq       [][]float64
	Wk       [][]float64
	Wv       [][]float64
	Wo       [][]float64
	ln1Scale []float64
	ln1Bias  []float64
	W1       [][]float64
	b1       []float64
	W2       [][]float64
	b2       []float64
	ln2Scale []float64
	ln2Bias  []float64
}

// TransformerV2 2-layer Transformer
type TransformerV2 struct {
	vocabSize int
	dModel    int

	// Embedding [vocab, dModel]
	embedding [][]float64

	// 2개 블록
	blocks [2]*TransformerBlock

	// Output projection [dModel, vocab]
	proj [][]float64
}

func newTransformerBlock(d, ffn int) *TransformerBlock {
	scale := math.Sqrt(2.0 / float64(d+d))
	fScale := math.Sqrt(2.0 / float64(d+ffn))
	return &TransformerBlock{
		Wq:       make2DRand(d, d, scale),
		Wk:       make2DRand(d, d, scale),
		Wv:       make2DRand(d, d, scale),
		Wo:       make2DRand(d, d, scale),
		ln1Scale: onesVec(d),
		ln1Bias:  zerosVec(d),
		W1:       make2DRand(d, ffn, fScale),
		b1:       zerosVec(ffn),
		W2:       make2DRand(ffn, d, fScale),
		b2:       zerosVec(d),
		ln2Scale: onesVec(d),
		ln2Bias:  zerosVec(d),
	}
}

func newTransformerV2(vocabSize int) *TransformerV2 {
	d := TDModel   // 256
	ffn := TDFFn   // 1024
	vScale := math.Sqrt(2.0 / float64(vocabSize+d))

	m := &TransformerV2{
		vocabSize: vocabSize,
		dModel:    d,
		embedding: make2DRand(vocabSize, d, vScale),
		proj:      make2DRand(d, vocabSize, vScale),
	}
	m.blocks[0] = newTransformerBlock(d, ffn)
	m.blocks[1] = newTransformerBlock(d, ffn)
	return m
}

// applyBlock 한 블록 forward: [seqLen, dModel] → [seqLen, dModel]
func applyBlock(X [][]float64, blk *TransformerBlock) [][]float64 {
	seqLen := len(X)

	// MHA
	attnOut := multiHeadAttention(X, blk.Wq, blk.Wk, blk.Wv, blk.Wo, TNumHead, TDHead)

	// Add & LN1
	for i := 0; i < seqLen; i++ {
		res := addResidual(X[i], attnOut[i])
		X[i] = layerNorm(res, blk.ln1Scale, blk.ln1Bias)
	}

	// FFN
	ffnOut := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		ffnOut[i] = feedForward(X[i], blk.W1, blk.b1, blk.W2, blk.b2)
	}

	// Add & LN2
	for i := 0; i < seqLen; i++ {
		res := addResidual(X[i], ffnOut[i])
		X[i] = layerNorm(res, blk.ln2Scale, blk.ln2Bias)
	}

	return X
}

// forwardV2 2-layer Transformer forward
func (m *TransformerV2) forwardV2(seq []int) []float64 {
	seqLen := len(seq)
	d := m.dModel

	// Embedding
	X := make([][]float64, seqLen)
	for i, tok := range seq {
		X[i] = make([]float64, d)
		if tok < m.vocabSize {
			copy(X[i], m.embedding[tok])
		}
	}

	// Block 1 → Block 2
	X = applyBlock(X, m.blocks[0])
	X = applyBlock(X, m.blocks[1])

	// Logits
	last := X[seqLen-1]
	logits := make([]float64, m.vocabSize)
	for v := 0; v < m.vocabSize; v++ {
		sum := 0.0
		for k := 0; k < d; k++ {
			sum += last[k] * m.proj[k][v]
		}
		logits[v] = sum
	}
	return logits
}

// ==================================================
// 학습 루프 (20 epochs)
// ==================================================

func trainTransformerV2() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase 6: 2-Layer Transformer + 20 Epochs                   ║")
	fmt.Println("║  d_model=256, 4-head MHA x2, FFN=1024 x2                   ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	fmt.Println("[1/5] Loading data...")
	tokens, vocab, err := tokenizeRealData("data/real_corpus_large.txt")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		return
	}
	fmt.Printf("✅ Loaded %d tokens, vocab=%d\n\n", len(tokens), len(vocab))

	fmt.Println("[2/5] Creating 2-layer Transformer...")
	model := newTransformerV2(len(vocab))
	d := TDModel
	ffn := TDFFn
	// 파라미터: embedding + 2×블록 + proj
	paramCount := len(vocab)*d + 2*(d*d*4+d*2+d*ffn+ffn+ffn*d+d+d*2) + d*len(vocab)
	fmt.Printf("✅ Parameters: ~%dk\n", paramCount/1000)
	fmt.Printf("   Layers: 2, d_model=%d, heads=%d, FFN=%d\n\n", TDModel, TNumHead, TDFFn)

	fmt.Println("[3/5] Initializing Adam...")
	adamEmb  := NewAdamState(0.0002, len(vocab)*d)
	adamProj := NewAdamState(0.0002, d*len(vocab))
	fmt.Printf("✅ Adam x2 (lr=0.0002)\n\n")

	seqLen := 32
	epochs := 20
	numBatches := 500
	warmupSteps := 1000
	totalSteps := epochs * numBatches

	fmt.Println("[4/5] Training config:")
	fmt.Printf("   Epochs: %d, Batches/epoch: %d\n", epochs, numBatches)
	fmt.Printf("   LR: 0.0002 (cosine + warmup %d steps)\n\n", warmupSteps)

	fmt.Println("[5/5] Training...")
	fmt.Println("══════════════════════════════════════════════════════════════")

	losses := make([]float64, 0, epochs)
	bestPPL := math.MaxFloat64

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0

		for batch := 0; batch < numBatches; batch++ {
			startIdx := rand.Intn(len(tokens) - seqLen - 1)
			seq := tokens[startIdx : startIdx+seqLen]
			targetTok := tokens[startIdx+seqLen]

			logits := model.forwardV2(seq)
			probs := softmax1D(logits)

			loss := 0.0
			if targetTok < len(probs) && probs[targetTok] > 1e-10 {
				loss = -math.Log(probs[targetTok])
			} else {
				loss = math.Log(float64(len(vocab)))
			}
			epochLoss += loss

			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if targetTok < len(dLogits) {
				dLogits[targetTok] -= 1.0
			}

			// LR schedule
			step := (epoch-1)*numBatches + batch + 1
			var lr float64
			if step < warmupSteps {
				lr = 0.0002 * float64(step) / float64(warmupSteps)
			} else {
				progress := float64(step-warmupSteps) / float64(totalSteps-warmupSteps)
				lr = 0.0002 * 0.5 * (1.0 + math.Cos(math.Pi*progress))
			}
			adamEmb.LearningRate = lr
			adamProj.LearningRate = lr

			// proj 업데이트
			lastTok := seq[seqLen-1]
			flatProj := flattenEmbedding(model.proj)
			gradsProj := make([]float64, len(flatProj))
			if lastTok < model.vocabSize {
				embVec := model.embedding[lastTok]
				for k := 0; k < d; k++ {
					for v := 0; v < model.vocabSize; v++ {
						gradsProj[k*model.vocabSize+v] = embVec[k] * dLogits[v]
					}
				}
			}
			updatedProj := adamProj.Step(flatProj, ClipGradient(gradsProj, 0.1))
			model.proj = unflattenEmbedding(updatedProj, d, model.vocabSize)

			// embedding 업데이트
			flatEmb := flattenEmbedding(model.embedding)
			gradsEmb := make([]float64, len(flatEmb))
			if targetTok < model.vocabSize {
				for k := 0; k < d; k++ {
					dEmb := 0.0
					for v := 0; v < model.vocabSize; v++ {
						dEmb += model.proj[k][v] * dLogits[v]
					}
					gradsEmb[targetTok*d+k] = dEmb
				}
			}
			updated := adamEmb.Step(flatEmb, ClipGradient(gradsEmb, 0.1))
			model.embedding = unflattenEmbedding(updated, model.vocabSize, d)

			if batch%100 == 0 {
				avg := epochLoss / float64(batch+1)
				fmt.Printf("Epoch %02d/%d, Batch %d/%d: Loss=%.4f PPL=%.2f LR=%.6f\r",
					epoch, epochs, batch+1, numBatches, avg, math.Exp(avg), lr)
			}
		}

		avgLoss := epochLoss / float64(numBatches)
		losses = append(losses, avgLoss)
		ppl := math.Exp(avgLoss)
		marker := ""
		if ppl < bestPPL {
			bestPPL = ppl
			marker = " ★ best"
		}
		fmt.Printf("\n✅ Epoch %02d: Loss=%.4f, PPL=%.2f%s\n", epoch, avgLoss, ppl, marker)
	}

	// 결과
	fmt.Println("\n══════════════════════════════════════════════════════════════")
	fmt.Println("📊 Training Curve:")
	for i, l := range losses {
		bar := ""
		if len(losses) > 1 && losses[0] > l {
			n := int((losses[0]-l)/losses[0]*40)
			for j := 0; j < n; j++ {
				bar += "█"
			}
		}
		fmt.Printf("  Epoch %02d: %s %.4f (PPL: %.2f)\n", i+1, bar, l, math.Exp(l))
	}

	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 Phase 6 Summary:\n")
		fmt.Printf("   Architecture: 2-layer Transformer\n")
		fmt.Printf("   d_model=%d, heads=%d, FFN=%d\n", TDModel, TNumHead, TDFFn)
		fmt.Printf("   Epochs:       %d\n", epochs)
		fmt.Printf("   Initial PPL:  %.2f\n", iPPL)
		fmt.Printf("   Final PPL:    %.2f\n", fPPL)
		fmt.Printf("   Best PPL:     %.2f ★\n", bestPPL)
		if imp > 0 {
			fmt.Printf("   Improvement:  %.1f%% ✅\n\n", imp)
		} else {
			fmt.Printf("   Degradation:  %.1f%% ⚠️\n\n", -imp)
		}
	}
}

