			var lr float64
			if step < warmupSteps {
				lr = 0.0002 * float64(step) / float64(warmupSteps)
			} else {
				progress := float64(step-warmupSteps) / float64(totalSteps-warmupSteps)
				lr = 0.0002 * 0.5 * (1.0 + math.Cos(math.Pi*progress))
			}
			adamEmb.LearningRate = lr
			adamProj.LearningRate = lr

			// proj 업데이트
			lastTok := seq[seqLen-1]
			flatProj := flattenEmbedding(model.proj)
			gradsProj := make([]float64, len(flatProj))
			if lastTok < model.vocabSize {
				embVec := model.embedding[lastTok]
				for k := 0; k < d; k++ {
					for v := 0; v < model.vocabSize; v++ {
						gradsProj[k*model.vocabSize+v] = embVec[k] * dLogits[v]
					}
				}
			}
			updatedProj := adamProj.Step(flatProj, ClipGradient(gradsProj, 0.1))
			model.proj = unflattenEmbedding(updatedProj, d, model.vocabSize)

			// embedding 업데이트
			flatEmb := flattenEmbedding(model.embedding)
			gradsEmb := make([]float64, len(flatEmb))
			if targetTok < model.vocabSize {
				for k := 0; k < d; k++ {
					dEmb := 0.0
					for v := 0; v < model.vocabSize; v++ {
						dEmb += model.proj[k][v] * dLogits[v]
					}
					gradsEmb[targetTok*d+k] = dEmb
				}
			}
			updated := adamEmb.Step(flatEmb, ClipGradient(gradsEmb, 0.1))
			model.embedding = unflattenEmbedding(updated, model.vocabSize, d)

			if batch%100 == 0 {
				avg := epochLoss / float64(batch+1)
				fmt.Printf("Epoch %02d/%d, Batch %d/%d: Loss=%.4f PPL=%.2f LR=%.6f\r",
					epoch, epochs, batch+1, numBatches, avg, math.Exp(avg), lr)
			}
		}

		avgLoss := epochLoss / float64(numBatches)
		losses = append(losses, avgLoss)
		ppl := math.Exp(avgLoss)
		marker := ""
		if ppl < bestPPL {
			bestPPL = ppl
			marker = " ★ best"
		}
		fmt.Printf("\n✅ Epoch %02d: Loss=%.4f, PPL=%.2f%s\n", epoch, avgLoss, ppl, marker)
	}

	// 결과
	fmt.Println("\n══════════════════════════════════════════════════════════════")
	fmt.Println("📊 Training Curve:")
	for i, l := range losses {
		bar := ""
		if len(losses) > 1 && losses[0] > l {
			n := int((losses[0]-l)/losses[0]*40)
			for j := 0; j < n; j++ {
				bar += "█"
			}
		}
		fmt.Printf("  Epoch %02d: %s %.4f (PPL: %.2f)\n", i+1, bar, l, math.Exp(l))
	}

	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 Phase 6 Summary:\n")
		fmt.Printf("   Architecture: 2-layer Transformer\n")
		fmt.Printf("   d_model=%d, heads=%d, FFN=%d\n", TDModel, TNumHead, TDFFn)
		fmt.Printf("   Epochs:       %d\n", epochs)
		fmt.Printf("   Initial PPL:  %.2f\n", iPPL)
		fmt.Printf("   Final PPL:    %.2f\n", fPPL)
		fmt.Printf("   Best PPL:     %.2f ★\n", bestPPL)
		if imp > 0 {
			fmt.Printf("   Improvement:  %.1f%% ✅\n\n", imp)
		} else {
			fmt.Printf("   Degradation:  %.1f%% ⚠️\n\n", -imp)
		}
	}
}

