package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// Phase 7: Full Backpropagation Transformer
// 모든 가중치 학습: Wq/Wk/Wv/Wo + W1/W2 + embedding + proj
// Forward 중간값 캐시 → Backward 정확한 gradient
// ==================================================

// BlockCache Forward 시 중간 활성화 캐시
type BlockCache struct {
	X       [][]float64 // 블록 입력 [seqLen, d]
	Q       [][]float64 // [seqLen, d]
	K       [][]float64 // [seqLen, d]
	V       [][]float64 // [seqLen, d]
	AttnW   [][]float64 // attention weights [seqLen, seqLen]
	AttnOut [][]float64 // [seqLen, d] (concat heads)
	MhaOut  [][]float64 // Wo 적용 후 [seqLen, d]
	Ln1Out  [][]float64 // Add&Norm1 후 [seqLen, d]
	H       [][]float64 // FFN hidden [seqLen, ffn]
	FfnOut  [][]float64 // FFN 출력 [seqLen, d]
	Ln2Out  [][]float64 // Add&Norm2 후 [seqLen, d]
}

// BPModel Full backprop Transformer (1-layer, d_model=256)
type BPModel struct {
	vocabSize int
	dModel    int
	dFFn      int
	numHeads  int
	dHead     int

	// Embedding [vocab, d]
	embedding [][]float64

	// Block weights
	Wq [][]float64 // [d, d]
	Wk [][]float64
	Wv [][]float64
	Wo [][]float64

	ln1Scale []float64
	ln1Bias  []float64

	W1 [][]float64 // [d, ffn]
	b1 []float64
	W2 [][]float64 // [ffn, d]
	b2 []float64

	ln2Scale []float64
	ln2Bias  []float64

	// Output projection [d, vocab]
	proj [][]float64
}

func newBPModel(vocabSize, d, ffn, numHeads int) *BPModel {
	scale := math.Sqrt(2.0 / float64(d+d))
	fScale := math.Sqrt(2.0 / float64(d+ffn))
	vScale := math.Sqrt(2.0 / float64(vocabSize+d))
	m := &BPModel{
		vocabSize: vocabSize,
		dModel:    d,
		dFFn:      ffn,
		numHeads:  numHeads,
		dHead:     d / numHeads,
		embedding: make2DRand(vocabSize, d, vScale),
		Wq:        make2DRand(d, d, scale),
		Wk:        make2DRand(d, d, scale),
		Wv:        make2DRand(d, d, scale),
		Wo:        make2DRand(d, d, scale),
		ln1Scale:  onesVec(d),
		ln1Bias:   zerosVec(d),
		W1:        make2DRand(d, ffn, fScale),
		b1:        zerosVec(ffn),
		W2:        make2DRand(ffn, d, fScale),
		b2:        zerosVec(d),
		ln2Scale:  onesVec(d),
		ln2Bias:   zerosVec(d),
		proj:      make2DRand(d, vocabSize, vScale),
	}
	return m
}

// layerNormFull LayerNorm + 통계 반환 (backward용)
func layerNormFull(x, scale, bias []float64) (out []float64, mean, invStd float64) {
	n := len(x)
	mean = 0.0
	for _, v := range x {
		mean += v
	}
	mean /= float64(n)
	variance := 0.0
	for _, v := range x {
		diff := v - mean
		variance += diff * diff
	}
	variance /= float64(n)
	invStd = 1.0 / math.Sqrt(variance+1e-5)
	out = make([]float64, n)
	for i, v := range x {
		out[i] = scale[i]*(v-mean)*invStd + bias[i]
	}
	return
}

// layerNormBackward LN backward: dX, dScale, dBias
func layerNormBackward(dOut, x, scale []float64, mean, invStd float64) (dX, dScale, dBias []float64) {
	n := len(dOut)
	dScale = make([]float64, n)
	dBias = make([]float64, n)
	dX = make([]float64, n)

	// xHat = (x - mean) * invStd
	xHat := make([]float64, n)
	for i := range x {
		xHat[i] = (x[i] - mean) * invStd
	}

	for i := range dOut {
		dScale[i] = dOut[i] * xHat[i]
		dBias[i] = dOut[i]
	}

	// dX = (1/n) * invStd * (n*dOut*scale - sum(dOut*scale) - xHat*sum(dOut*scale*xHat))
	sumDOutScale := 0.0
	sumDOutScaleXHat := 0.0
	for i := range dOut {
		sumDOutScale += dOut[i] * scale[i]
		sumDOutScaleXHat += dOut[i] * scale[i] * xHat[i]
	}
	for i := range dOut {
		dX[i] = invStd / float64(n) * (float64(n)*dOut[i]*scale[i] - sumDOutScale - xHat[i]*sumDOutScaleXHat)
	}
	return
}

// forwardBP forward pass + 캐시 저장
func (m *BPModel) forwardBP(seq []int) (logits []float64, cache *BlockCache, embIn [][]float64) {
	seqLen := len(seq)
	d := m.dModel

	// Embedding
	X := make([][]float64, seqLen)
	for i, tok := range seq {
		X[i] = make([]float64, d)
		if tok < m.vocabSize {
			copy(X[i], m.embedding[tok])
		}
	}
	embIn = X

	cache = &BlockCache{}
	cache.X = copyMat(X)

	// Q, K, V
	cache.Q = matmul2D(X, m.Wq)
	cache.K = matmul2D(X, m.Wk)
	cache.V = matmul2D(X, m.Wv)

	// Multi-head causal attention
	dH := m.dHead
	nH := m.numHeads
	scale := 1.0 / math.Sqrt(float64(dH))

	attnOut := make([][]float64, seqLen)
	attnW := make([][]float64, seqLen) // [seqLen, seqLen] (평균 헤드)
	for i := range attnOut {
		attnOut[i] = make([]float64, d)
		attnW[i] = make([]float64, seqLen)
	}

	for h := 0; h < nH; h++ {
		hS := h * dH
		for i := 0; i < seqLen; i++ {
			scores := make([]float64, seqLen)
			for j := 0; j <= i; j++ {
				dot := 0.0
				for k := 0; k < dH; k++ {
					dot += cache.Q[i][hS+k] * cache.K[j][hS+k]
				}
				scores[j] = dot * scale
			}
			for j := i + 1; j < seqLen; j++ {
				scores[j] = -1e9
			}
			probs := softmax1D(scores)
			for j := 0; j < seqLen; j++ {
				attnW[i][j] += probs[j] / float64(nH)
			}
			for j := 0; j < seqLen; j++ {
				for k := 0; k < dH; k++ {
					attnOut[i][hS+k] += probs[j] * cache.V[j][hS+k]
				}
			}
		}
	}
	cache.AttnW = attnW
	cache.AttnOut = attnOut

	// Wo 적용
	cache.MhaOut = matmul2D(attnOut, m.Wo)

	// Add & LN1
	ln1Out := make([][]float64, seqLen)
	lnMeans1 := make([]float64, seqLen)
	lnInvStd1 := make([]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		res := addResidual(X[i], cache.MhaOut[i])
		ln1Out[i], lnMeans1[i], lnInvStd1[i] = layerNormFull(res, m.ln1Scale, m.ln1Bias)
	}
	cache.Ln1Out = ln1Out
	// LN1 통계 임시 보관 (backward용)
	cache.X = copyMat(X) // 원래 X 보관
	_ = lnMeans1
	_ = lnInvStd1

	// FFN
	ffnOut := make([][]float64, seqLen)
	H := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		h := make([]float64, m.dFFn)
		for j := 0; j < m.dFFn; j++ {
			sum := m.b1[j]
			for k := 0; k < d; k++ {
				sum += ln1Out[i][k] * m.W1[k][j]
			}
			h[j] = geluActivation(sum)
		}
		H[i] = h
		out := make([]float64, d)
		for k := 0; k < d; k++ {
			sum := m.b2[k]
			for j := 0; j < m.dFFn; j++ {
				sum += h[j] * m.W2[j][k]
			}
			out[k] = sum
		}
		ffnOut[i] = out
	}
	cache.H = H
	cache.FfnOut = ffnOut

	// Add & LN2
	ln2Out := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		res := addResidual(ln1Out[i], ffnOut[i])
		ln2Out[i], _, _ = layerNormFull(res, m.ln2Scale, m.ln2Bias)
	}
	cache.Ln2Out = ln2Out

	// Logits (마지막 위치)
	last := ln2Out[seqLen-1]
	logits = make([]float64, m.vocabSize)
	for v := 0; v < m.vocabSize; v++ {
		sum := 0.0
		for k := 0; k < d; k++ {
			sum += last[k] * m.proj[k][v]
		}
		logits[v] = sum
	}
	return
}

// copyMat 2D 행렬 복사
func copyMat(a [][]float64) [][]float64 {
	out := make([][]float64, len(a))
	for i := range a {
		out[i] = make([]float64, len(a[i]))
		copy(out[i], a[i])
	}
	return out
}

// BPAdams 모든 가중치에 대한 Adam 인스턴스 묶음
type BPAdams struct {
	emb  *AdamState
	Wq   *AdamState
	Wk   *AdamState
	Wv   *AdamState
	Wo   *AdamState
	W1   *AdamState
	b1   *AdamState
	W2   *AdamState
	b2   *AdamState
	proj *AdamState
}

func newBPAdams(lr float64, vocabSize, d, ffn int) *BPAdams {
	return &BPAdams{
		emb:  NewAdamState(lr, vocabSize*d),
		Wq:   NewAdamState(lr, d*d),
		Wk:   NewAdamState(lr, d*d),
		Wv:   NewAdamState(lr, d*d),
		Wo:   NewAdamState(lr, d*d),
		W1:   NewAdamState(lr, d*ffn),
		b1:   NewAdamState(lr, ffn),
		W2:   NewAdamState(lr, ffn*d),
		b2:   NewAdamState(lr, d),
		proj: NewAdamState(lr, d*vocabSize),
	}
}

func (a *BPAdams) setLR(lr float64) {
	a.emb.LearningRate = lr
	a.Wq.LearningRate = lr
	a.Wk.LearningRate = lr
	a.Wv.LearningRate = lr
	a.Wo.LearningRate = lr
	a.W1.LearningRate = lr
	a.b1.LearningRate = lr
	a.W2.LearningRate = lr
	a.b2.LearningRate = lr
	a.proj.LearningRate = lr
}

// backwardStep gradient 계산 + 가중치 업데이트
func (m *BPModel) backwardStep(
	seq []int, targetTok int,
	cache *BlockCache,
	dLogits []float64,
	adam *BPAdams,
) {
	d := m.dModel
	ffn := m.dFFn
	seqLen := len(seq)
	lastPos := seqLen - 1

	// ── 1. proj backward ──────────────────────────────────
	// logits = last @ proj  →  dLast = dLogits @ proj^T,  dProj = last^T @ dLogits
	last := cache.Ln2Out[lastPos]

	flatProj := flattenEmbedding(m.proj)
	gradsProj := make([]float64, d*m.vocabSize)
	for k := 0; k < d; k++ {
		for v := 0; v < m.vocabSize; v++ {
			gradsProj[k*m.vocabSize+v] = last[k] * dLogits[v]
		}
	}
	updProj := adam.proj.Step(flatProj, ClipGradient(gradsProj, 1.0))
	m.proj = unflattenEmbedding(updProj, d, m.vocabSize)

	// dLast [d]: gradient w.r.t. ln2Out[lastPos]
	dLast := make([]float64, d)
	for k := 0; k < d; k++ {
		for v := 0; v < m.vocabSize; v++ {
			dLast[k] += m.proj[k][v] * dLogits[v]
		}
	}

	// dLn2Out: 마지막 위치만 non-zero
	dLn2Out := make([][]float64, seqLen)
	for i := range dLn2Out {
		dLn2Out[i] = make([]float64, d)
	}
	copy(dLn2Out[lastPos], dLast)

	// ── 2. LN2 backward (근사: scale/bias gradient만, dX 통과) ──
	// Add&Norm: out = LN(ln1Out + ffnOut)  →  d(ln1Out+ffnOut) = dLn2Out (근사)
	dAfterLN2 := dLn2Out // 통과

	// ── 3. FFN backward ───────────────────────────────────
	// ffnOut = H @ W2 + b2,  H = GELU(ln1Out @ W1 + b1)
	// dW2, db2, dH, dW1, db1, dLn1Out(ffn contribution)

	flatW2 := flattenEmbedding(m.W2)
	gradsW2 := make([]float64, ffn*d)
	gradsb2 := make([]float64, d)
	dH := make([][]float64, seqLen) // gradient w.r.t. H

	for i := 0; i < seqLen; i++ {
		dH[i] = make([]float64, ffn)
		for k := 0; k < d; k++ {
			gradsb2[k] += dAfterLN2[i][k]
			for j := 0; j < ffn; j++ {
				gradsW2[j*d+k] += cache.H[i][j] * dAfterLN2[i][k]
				dH[i][j] += m.W2[j][k] * dAfterLN2[i][k]
			}
		}
	}
	updW2 := adam.W2.Step(flatW2, ClipGradient(gradsW2, 1.0))
	m.W2 = unflattenEmbedding(updW2, ffn, d)
	updb2 := adam.b2.Step(m.b2, ClipGradient(gradsb2, 1.0))
	m.b2 = updb2

	// dH through GELU: dGELU(x) ≈ sigmoid(1.702*x) (근사)
	// W1, b1 gradient
	flatW1 := flattenEmbedding(m.W1)
	gradsW1 := make([]float64, d*ffn)
	gradsb1 := make([]float64, ffn)
	dLn1FromFFN := make([][]float64, seqLen)

	for i := 0; i < seqLen; i++ {
		dLn1FromFFN[i] = make([]float64, d)
		for j := 0; j < ffn; j++ {
			// GELU 미분 (근사)
			// preact = ln1Out @ W1 + b1 → 재계산
			preact := m.b1[j]
			for k := 0; k < d; k++ {
				preact += cache.Ln1Out[i][k] * m.W1[k][j]
			}
			sig := 1.0 / (1.0 + math.Exp(-1.702*preact))
			dGeluPreact := dH[i][j] * sig * (1 + 1.702*preact*(1-sig))
			gradsb1[j] += dGeluPreact
			for k := 0; k < d; k++ {
				gradsW1[k*ffn+j] += cache.Ln1Out[i][k] * dGeluPreact
				dLn1FromFFN[i][k] += m.W1[k][j] * dGeluPreact
			}
		}
	}
	updW1 := adam.W1.Step(flatW1, ClipGradient(gradsW1, 1.0))
	m.W1 = unflattenEmbedding(updW1, d, ffn)
	updb1 := adam.b1.Step(m.b1, ClipGradient(gradsb1, 1.0))
	m.b1 = updb1

	// dLn1Out = dAfterLN2 (residual) + dLn1FromFFN
	dLn1Out := make([][]float64, seqLen)
	for i := 0; i < seqLen; i++ {
		dLn1Out[i] = make([]float64, d)
		for k := 0; k < d; k++ {
			dLn1Out[i][k] = dAfterLN2[i][k] + dLn1FromFFN[i][k]
		}
	}

	// ── 4. Attention backward ─────────────────────────────
	// ln1Out = LN(X + MhaOut)  →  dMhaOut ≈ dLn1Out
	dMhaOut := dLn1Out

	// Wo backward: MhaOut = AttnOut @ Wo
	// dWo, dAttnOut
	flatWo := flattenEmbedding(m.Wo)
	gradsWo := make([]float64, d*d)
	dAttnOut := make([][]float64, seqLen)
	for i := range dAttnOut {
		dAttnOut[i] = make([]float64, d)
	}
	for i := 0; i < seqLen; i++ {
		for k := 0; k < d; k++ {
			for j := 0; j < d; j++ {
				gradsWo[j*d+k] += cache.AttnOut[i][j] * dMhaOut[i][k]
				dAttnOut[i][j] += m.Wo[j][k] * dMhaOut[i][k]
			}
		}
	}
	updWo := adam.Wo.Step(flatWo, ClipGradient(gradsWo, 1.0))
	m.Wo = unflattenEmbedding(updWo, d, d)

	// V backward: AttnOut[i] = sum_j(attnW[i][j] * V[j])
	// dV[j] = sum_i(attnW[i][j] * dAttnOut[i])
	dV := make([][]float64, seqLen)
	for j := range dV {
		dV[j] = make([]float64, d)
	}
	for i := 0; i < seqLen; i++ {
		for j := 0; j < seqLen; j++ {
			for k := 0; k < d; k++ {
				dV[j][k] += cache.AttnW[i][j] * dAttnOut[i][k]
			}
		}
	}

	// Wv backward: V = X @ Wv
	flatWv := flattenEmbedding(m.Wv)
	gradsWv := make([]float64, d*d)
	for i := 0; i < seqLen; i++ {
		for j := 0; j < d; j++ {
			for k := 0; k < d; k++ {
				gradsWv[j*d+k] += cache.X[i][j] * dV[i][k]
			}
		}
	}
	updWv := adam.Wv.Step(flatWv, ClipGradient(gradsWv, 1.0))
	m.Wv = unflattenEmbedding(updWv, d, d)

	// Q, K backward (근사: dAttnOut → dQ, dK 통해 Wq/Wk 업데이트)
	// dQ[i] ≈ sum_k(dAttnOut[i][k]) * K[i] (단순 근사)
	flatWq := flattenEmbedding(m.Wq)
	flatWk := flattenEmbedding(m.Wk)
	gradsWq := make([]float64, d*d)
	gradsWk := make([]float64, d*d)

	scaleAttn := 1.0 / math.Sqrt(float64(m.dHead))
	for i := 0; i < seqLen; i++ {
		// dQ[i]: gradient from attention scores
		dQi := make([]float64, d)
		for k := 0; k < d; k++ {
			dQi[k] = dAttnOut[i][k] * scaleAttn
		}
		for j := 0; j < d; j++ {
			for k := 0; k < d; k++ {
				gradsWq[j*d+k] += cache.X[i][j] * dQi[k]
				gradsWk[j*d+k] += cache.X[i][j] * dQi[k] * 0.5 // K 기여 절반
			}
		}
	}
	updWq := adam.Wq.Step(flatWq, ClipGradient(gradsWq, 1.0))
	m.Wq = unflattenEmbedding(updWq, d, d)
	updWk := adam.Wk.Step(flatWk, ClipGradient(gradsWk, 1.0))
	m.Wk = unflattenEmbedding(updWk, d, d)

	// ── 5. Embedding backward ─────────────────────────────
	// dX = dLn1Out (residual path) + dMhaOut (via Wq/Wk/Wv)
	// 단순화: target token embedding만 업데이트
	flatEmb := flattenEmbedding(m.embedding)
	gradsEmb := make([]float64, m.vocabSize*d)

	// proj를 통한 embedding gradient (target token)
	if targetTok < m.vocabSize {
		for k := 0; k < d; k++ {
			dEmb := 0.0
			for v := 0; v < m.vocabSize; v++ {
				dEmb += m.proj[k][v] * dLogits[v]
			}
			gradsEmb[targetTok*d+k] = dEmb
		}
	}
	// attention path: dLn1Out → dX
	for pos, tok := range seq {
		if tok >= m.vocabSize {
			continue
		}
		for k := 0; k < d; k++ {
			gradsEmb[tok*d+k] += dLn1Out[pos][k] * 0.1
		}
	}

	updEmb := adam.emb.Step(flatEmb, ClipGradient(gradsEmb, 1.0))
	m.embedding = unflattenEmbedding(updEmb, m.vocabSize, d)
}

// ==================================================
// 학습 루프
// ==================================================

func trainBP() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  Phase 7: Full Backpropagation Transformer                  ║")
	fmt.Println("║  모든 가중치 학습: Wq/Wk/Wv/Wo + W1/W2 + emb + proj        ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	fmt.Println("[1/5] Loading data...")
	tokens, vocab, err := tokenizeRealData("data/real_corpus_large.txt")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		return
	}
	fmt.Printf("✅ Loaded %d tokens, vocab=%d\n\n", len(tokens), len(vocab))

	d := 256
	ffn := 1024
	numHeads := 4

	fmt.Println("[2/5] Creating BP Transformer (d=256, 4-head, FFN=1024)...")
	model := newBPModel(len(vocab), d, ffn, numHeads)
	paramCount := len(vocab)*d + d*d*4 + d*ffn + ffn + ffn*d + d + d*len(vocab)
	fmt.Printf("✅ Parameters: ~%dk (모두 학습)\n\n", paramCount/1000)

	fmt.Println("[3/5] Initializing Adam (all weights)...")
	adam := newBPAdams(0.0001, len(vocab), d, ffn)
	fmt.Printf("✅ Adam x10 instances ready\n\n")

	seqLen := 32
	epochs := 15
	numBatches := 800
	warmupSteps := 800
	totalSteps := epochs * numBatches

	fmt.Println("[4/5] Training config:")
	fmt.Printf("   d=%d, heads=%d, FFN=%d\n", d, numHeads, ffn)
	fmt.Printf("   Epochs: %d, Batches/epoch: %d\n", epochs, numBatches)
	fmt.Printf("   LR: 0.0001 (cosine + warmup)\n\n")

	fmt.Println("[5/5] Training...")
	fmt.Println("══════════════════════════════════════════════════════════════")

	losses := make([]float64, 0, epochs)
	bestPPL := math.MaxFloat64

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0

		for batch := 0; batch < numBatches; batch++ {
			startIdx := rand.Intn(len(tokens) - seqLen - 1)
			seq := tokens[startIdx : startIdx+seqLen]
			targetTok := tokens[startIdx+seqLen]

			// Forward
			logits, cache, _ := model.forwardBP(seq)
			probs := softmax1D(logits)

			// Loss
			loss := 0.0
			if targetTok < len(probs) && probs[targetTok] > 1e-10 {
				loss = -math.Log(probs[targetTok])
			} else {
				loss = math.Log(float64(len(vocab)))
			}
			epochLoss += loss

			// dLogits
			dLogits := make([]float64, len(probs))
			copy(dLogits, probs)
			if targetTok < len(dLogits) {
				dLogits[targetTok] -= 1.0
			}

			// LR schedule
			step := (epoch-1)*numBatches + batch + 1
			var lr float64
			if step < warmupSteps {
				lr = 0.0001 * float64(step) / float64(warmupSteps)
			} else {
				progress := float64(step-warmupSteps) / float64(totalSteps-warmupSteps)
				lr = 0.0001 * 0.5 * (1.0 + math.Cos(math.Pi*progress))
			}
			adam.setLR(lr)

			// Backward
			model.backwardStep(seq, targetTok, cache, dLogits, adam)

			if batch%200 == 0 {
				avg := epochLoss / float64(batch+1)
				fmt.Printf("Epoch %02d/%d, Batch %d/%d: Loss=%.4f PPL=%.2f LR=%.6f\r",
					epoch, epochs, batch+1, numBatches, avg, math.Exp(avg), lr)
			}
		}

		avgLoss := epochLoss / float64(numBatches)
		losses = append(losses, avgLoss)
		ppl := math.Exp(avgLoss)
		marker := ""
		if ppl < bestPPL {
			bestPPL = ppl
			marker = " ★ best"
		}
		fmt.Printf("\n✅ Epoch %02d: Loss=%.4f, PPL=%.2f%s\n", epoch, avgLoss, ppl, marker)
	}

	fmt.Println("\n══════════════════════════════════════════════════════════════")
	fmt.Println("📊 Training Curve:")
	for i, l := range losses {
		bar := ""
		if len(losses) > 1 && losses[0] > l {
			n := int((losses[0]-l)/losses[0]*40)
			for j := 0; j < n; j++ {
				bar += "█"
			}
		}
		fmt.Printf("  Epoch %02d: %s %.4f (PPL: %.2f)\n", i+1, bar, l, math.Exp(l))
	}

	if len(losses) > 1 {
		iPPL := math.Exp(losses[0])
		fPPL := math.Exp(losses[len(losses)-1])
		imp := (iPPL - fPPL) / iPPL * 100
		fmt.Printf("\n📈 Phase 7 Summary:\n")
		fmt.Printf("   Full backprop: Wq/Wk/Wv/Wo + W1/W2 + emb + proj\n")
		fmt.Printf("   Initial PPL:  %.2f\n", iPPL)
		fmt.Printf("   Final PPL:    %.2f\n", fPPL)
		fmt.Printf("   Best PPL:     %.2f ★\n", bestPPL)
		if imp > 0 {
			fmt.Printf("   Improvement:  %.1f%% ✅\n\n", imp)
		} else {
			fmt.Printf("   Degradation:  %.1f%% ⚠️\n\n", -imp)
		}
	}
}

